<?= $this->extend('layout') ?><?= $this->section('content') ?><section class="card"><h1>Edit Staff Member</h1><?php $avatar=!empty($user['avatar'])?basename($user['avatar']):'placeholder.svg'; ?><p><img class="thumb" src="<?= base_url('uploads/avatars/'.rawurlencode($avatar)) ?>" alt="Current avatar of <?= esc($user['full_name']) ?>"></p><form method="post" enctype="multipart/form-data" action="<?= site_url('users/'.$user['id']) ?>"><?= csrf_field() ?><label for="username">Username</label><input id="username" name="username" minlength="3" maxlength="50" pattern="[A-Za-z0-9]+" required value="<?= esc(old('username',$user['username'])) ?>"><label for="full_name">Full name</label><input id="full_name" name="full_name" maxlength="100" required value="<?= esc(old('full_name',$user['full_name'])) ?>"><label for="password">New password</label><input id="password" type="password" name="password" minlength="10" maxlength="255"><small>Optional. Leave blank to keep the current password.</small><label for="avatar">New avatar</label><input id="avatar" type="file" name="avatar" accept="image/jpeg,image/png"><small>Optional JPG or PNG image, maximum 2 MB.</small><p><button>Save Changes</button> <a href="<?= site_url('users') ?>">Cancel</a></p></form></section><?= $this->endSection() ?>
